describe('Optimistic UI Updates - Like Post', () => {
  const baseUrl = 'http://localhost:3000';
  const postId = '12345';
  const userId = 'user-001';

  beforeEach(() => {
    cy.visit(`${baseUrl}/posts/${postId}`);
    cy.intercept('POST', `/api/posts/${postId}/like`, {
      statusCode: 200,
      body: { success: true, likeCount: 42 }
    }).as('likePost');
    cy.intercept('GET', `/api/posts/${postId}`, {
      statusCode: 200,
      body: {
        id: postId,
        title: 'Test Post',
        content: 'This is a test post',
        likeCount: 41,
        isLiked: false
      }
    }).as('getPost');
  });

  it('should update UI immediately when liking a post before API response', () => {
    cy.get('[data-testid="like-button"]').should('exist');
    cy.get('[data-testid="like-count"]').should('contain', '41');
    cy.get('[data-testid="like-button"]').should('not.have.class', 'liked');

    cy.get('[data-testid="like-button"]').click();

    // Optimistic update should happen immediately
    cy.get('[data-testid="like-count"]').should('contain', '42');
    cy.get('[data-testid="like-button"]').should('have.class', 'liked');

    // Wait for API response
    cy.wait('@likePost');

    // UI should remain in the updated state
    cy.get('[data-testid="like-count"]').should('contain', '42');
    cy.get('[data-testid="like-button"]').should('have.class', 'liked');
  });

  it('should revert optimistic update if API request fails', () => {
    cy.intercept('POST', `/api/posts/${postId}/like`, {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('likePostFailed');

    cy.get('[data-testid="like-button"]').should('exist');
    cy.get('[data-testid="like-count"]').should('contain', '41');

    cy.get('[data-testid="like-button"]').click();

    // Optimistic update should happen immediately
    cy.get('[data-testid="like-count"]').should('contain', '42');
    cy.get('[data-testid="like-button"]').should('have.class', 'liked');

    // Wait for failed API response
    cy.wait('@likePostFailed');

    // UI should revert to original state
    cy.get('[data-testid="like-count"]').should('contain', '41');
    cy.get('[data-testid="like-button"]').should('not.have.class', 'liked');

    // Error message should be displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to like post');
  });

  it('should handle rapid consecutive like clicks with optimistic updates', () => {
    cy.intercept('POST', `/api/posts/${postId}/like`, (req) => {
      req.reply((res) => {
        res.delay(1000);
        res.send({
          statusCode: 200,
          body: { success: true, likeCount: 42 }
        });
      });
    }).as('likePostDelayed');

    cy.get('[data-testid="like-button"]').click();
    cy.get('[data-testid="like-count"]').should('contain', '42');

    // Second click should be prevented or handled gracefully
    cy.get('[data-testid="like-button"]').should('be.disabled');

    cy.wait('@likePostDelayed');

    cy.get('[data-testid="like-button"]').should('not.be.disabled');
    cy.get('[data-testid="like-count"]').should('contain', '42');
  });

  it('should maintain optimistic state across page navigation and return', () => {
    cy.get('[data-testid="like-button"]').click();
    cy.get('[data-testid="like-count"]').should('contain', '42');

    cy.wait('@likePost');

    // Navigate away
    cy.visit(`${baseUrl}/posts`);

    // Navigate back
    cy.visit(`${baseUrl}/posts/${postId}`);

    // Should reflect the liked state from API
    cy.intercept('GET', `/api/posts/${postId}`, {
      statusCode: 200,
      body: {
        id: postId,
        title: 'Test Post',
        content: 'This is a test post',
        likeCount: 42,
        isLiked: true
      }
    }).as('getPostLiked');

    cy.wait('@getPostLiked');

    cy.get('[data-testid="like-count"]').should('contain', '42');
    cy.get('[data-testid="like-button"]').should('have.class', 'liked');
  });

  it('should show loading state during API request if optimistic update is delayed', () => {
    cy.intercept('POST', `/api/posts/${postId}/like`, (req) => {
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: { success: true, likeCount: 42 }
        });
      });
    }).as('likePostSlow');

    cy.get('[data-testid="like-button"]').click();

    // Optimistic update should be immediate
    cy.get('[data-testid="like-count"]').should('contain', '42');

    // Loading indicator should appear
    cy.get('[data-testid="like-button"]').should('have.class', 'loading');

    cy.wait('@likePostSlow');

    // Loading state should be removed
    cy.get('[data-testid="like-button"]').should('not.have.class', 'loading');
  });
});
